        move("cold_run_release_firstborn (CALL) — RF.the_needy_and_the_blessing(lend_not_borrow) = %s" % (RF_LEND[0][:80],), "lend and not borrow — 15:6's clause said again with the lending verb; 28:44's reversal the curse's arm")
