def the_curses_of_the_house_and_the_field(case, data):
    """F9 — Deut 28:15-44 — FIVE LINES: curses_condition_declared (28:15-19) writing curses_for_not_hearkening and the four twins (HEAVEN); curse_diseases_brass_declared (28:20-24) six; defeat_carcass_boil_madness_declared (28:25-29) four; wife_house_vineyard_king_taken_declared (28:30-37) seven; harvests_failed_stranger_head_declared (28:38-44) three — twenty-five HEAVEN entries, the state row's second arm; the kin by CALL (tochacha — Leviticus 26 the twin diffed; blessing_and_curse, good_land, seven_nations, refuge_war_family, courts_prophet, obey_horeb, exodus_story, release_firstborn, food_tithe, ordinances)"""
    del P_[:]
    ask = case['ask']
    if ask == 'if_you_will_not_hearken_all_these_curses':
        ink('28:15', "'AND IT SHALL BE, IF YOU WILL NOT HEARKEN TO THE VOICE OF THE LORD YOUR GOD to keep and do all His commandments and His statutes which I command you this day, ALL THESE CURSES SHALL COME UPON YOU and overtake you' — 28:1's negation %d tokens in order (THE STATE ROW's second arm); 'not hearken to the voice' 28:15, 45, 62" % (TWIN['28:1 vs 28:15'],))
        move("cold_run_blessing_and_curse (CALL) — BC.the_blessing_and_the_curse(the_curse_if) = %s (11:28's 'the curse, if you do not hearken'; blessing_and_curse_set ONE on Israel, count %s UNMOVED); cold_run_good_land (CALL) — GL.the_testimony(hearken_plural) = %s (8:19-20's testimony — its own forward reading of 28:15, 45, 62)" % (BC_CURSEIF[0][:60], KIN_COUNTS['blessing_and_curse_set'], GL_HEAR[0][:60]), "the curses for not hearkening — the state row's second arm, the mirror of blessings_for_hearing; 11:28's curse and 8:20's testimony the kin")
        dat("THE WRITE curses_for_not_hearkening — a conditional HEAVEN entry on israel_people at the chapters' own day (DL2) — the state row's second arm (28:15 state=True); the exam's person the people who do not hearken — the curse's arm")
        return out("if you will not hearken, all these curses (28:15) — 28:1's negation sixteen in order, the state row's second arm; 11:28's curse and 8:20's testimony the kin (blessing_and_curse's %s and good_land's %s by CALL): THE WRITE curses_for_not_hearkening, a conditional HEAVEN entry on Israel at the chapters' own day" % (BC_CURSEIF[0][:30], GL_HEAR[0][:30]), ['curses_for_not_hearkening'])
    def _twin(ask):
        V_, E_, T_ = {'cursed_in_the_city_and_in_the_field': ('28:16', 'cursed_in_city_and_field', '28:3 vs 28:16'), 'cursed_your_basket_and_your_kneading_trough': ('28:17', 'cursed_basket_and_trough', '28:5 vs 28:17'), 'cursed_the_fruit_of_womb_ground_and_beast': ('28:18', 'cursed_fruit_of_womb_ground_beast', '28:4 vs 28:18'), 'cursed_coming_in_and_going_out': ('28:19', 'cursed_coming_in_and_going_out', '28:6 vs 28:19')}[ask]
        ink(V_, "'CURSED …' — the twin of the blessing seat for seat (%s shares %d tokens); 'cursed' the four twins' word (%s the Torah's seats of the token)" % (T_, TWIN[T_], len(U(_G('ארור (cursed)'), books=T))))
        move("the Sifrei 40:11 (on 11:12 — 'the measure of good exceeds the measure of punishment: is it not in My power to curse in the house as in the field?' — Haggai 1:9 the answer, a Prophets seat not read); cold_run_tochacha (CALL) — TC.cascade(4)['stage'] = %s (Leviticus 26:26's 'you shall eat and not be satisfied' the innards' curse beside the twins); cold_run_ordinances (CALL) — OR.land(no_barren) = %s (23:26's clause the blessing's kin)" % (TC_C4['stage']['v'], OR_BARREN['v']), "the four twins — the store, the dough, the womb and the ground (the beast's fruit dropped), coming and going: the shelf's table 40:11 seat for seat; the state row's second arm")
        dat("THE WRITE %s — a HEAVEN entry on israel_people at the chapters' own day (DL2), the twin of its blessing; the_hearkening_state's twelve twins a DATA row; the exam's person the household cursed in the seat its blessing named — the mirror" % (E_,))
        return out("%s (%s) — the blessing's twin seat for seat (%d shared), the shelf's table 40:11 (tochacha's stage %s by CALL): THE WRITE %s, a HEAVEN entry on Israel at the chapters' own day" % (ask.replace('_', ' '), V_, TWIN[T_], TC_C4['stage']['v'], E_), [E_])
